using KY.Core.DataAccess;
using KY.Generator.Models;
using KY.Generator.Output;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace KY.Generator.Tests;

/// <summary>
/// A generated file can belong to more than one project, each one leaves its output id in it. A parallel build runs
/// the generators of those projects at the same time - see <see cref="OutputWriteAction"/> and
/// <see cref="OutputRemoveIdAction"/>
/// </summary>
[TestClass]
public class OutputActionTests
{
    private const string Content = "// <auto-generated>\nexport class Model {}\n";
    private string root = null!;
    private string filePath = null!;

    [TestInitialize]
    public void Initialize()
    {
        this.root = FileSystem.Combine(Path.GetTempPath(), "KY.Generator.Tests", Guid.NewGuid().ToString("N"));
        this.filePath = FileSystem.Combine(this.root, "model.ts");
        FileSystem.CreateDirectory(this.root);
    }

    [TestCleanup]
    public void Cleanup()
    {
        FileSystem.DeleteDirectory(this.root);
    }

    [TestMethod]
    public void EveryProjectThatWritesTheSameFileInParallelKeepsItsId()
    {
        List<Guid> ids = Enumerable.Range(0, 8).Select(_ => Guid.NewGuid()).ToList();

        ids.AsParallel().WithDegreeOfParallelism(ids.Count).ForAll(this.Write);

        CollectionAssert.AreEquivalent(ids, OutputFileHelper.GetOutputIds(FileSystem.ReadAllText(this.filePath)));
    }

    [TestMethod]
    public void EveryProjectThatRemovesItselfInParallelIsRemoved()
    {
        List<Guid> ids = Enumerable.Range(0, 8).Select(_ => Guid.NewGuid()).ToList();
        ids.ForEach(this.Write);
        List<Guid> removed = ids.Take(6).ToList();

        removed.AsParallel().WithDegreeOfParallelism(removed.Count).ForAll(id => new OutputRemoveIdAction(this.filePath, id).Execute());

        CollectionAssert.AreEquivalent(ids.Skip(6).ToList(), OutputFileHelper.GetOutputIds(FileSystem.ReadAllText(this.filePath)));
    }

    [TestMethod]
    public void TheFileIsDeletedWithTheLastId()
    {
        Guid first = Guid.NewGuid();
        Guid second = Guid.NewGuid();
        this.Write(first);
        this.Write(second);

        new OutputRemoveIdAction(this.filePath, first).Execute();
        Assert.IsTrue(FileSystem.FileExists(this.filePath), "Another project still generates the file");

        new OutputRemoveIdAction(this.filePath, second).Execute();
        Assert.IsFalse(FileSystem.FileExists(this.filePath), "No project generates the file any more");
    }

    private void Write(Guid outputId)
    {
        new OutputWriteAction(this.filePath, Content, new GeneratorOptions(null, null), new GeneratorEnvironment(), outputId).Execute();
    }
}
